"""Generate the review guide from the exact campaign polygons and verified routes."""
from pathlib import Path
import json,html
root=Path(__file__).resolve().parents[2];out=root/'design/expedition_013'
campaign=json.loads((root/'design/runtime_campaign_20x5.json').read_text());design=json.loads((out/'stage_design.json').read_text())['stages'];crew=json.loads((out/'crew.json').read_text());names={r['id']:r['name']['ja'] for r in crew}
esc=lambda x:html.escape(str(x),quote=True)
feature_names={'W':'反射床','K':'反射結晶','B':'開閉橋','C':'減速する雲','U':'上昇流','F':'風','V':'噴出孔','M':'磁場','T':'切替端子'}
def polygon(points,cl):return '<polygon class="'+cl+'" points="'+' '.join(f'{x},{50-y}' for x,y in points)+'"/>'
def miniature(l):
    parts=['<svg viewBox="0 -12 100 80" role="img" aria-label="'+esc(l['name'])+'の実データによる地形輪郭"><rect x="0" y="-12" width="100" height="80" fill="#204858"/>']
    for floor in l['floors']:parts.append(polygon(floor+[[floor[-1][0],-18],[floor[0][0],-18]],'ground'))
    for p in l['components']:parts.append(polygon(p['poly'],'breakable' if p['destructible'] else 'fixed'))
    for f in l['features']:
        v=f['v'];kind=f['type']
        if kind in ['W','B']:parts.append(f'<path class="device" d="M{v[0]} {50-v[2]}H{v[1]}"/>')
        elif kind=='K':parts.append(f'<path class="device" d="M{v[0]-2} {50-v[1]}l2 -3 2 3 -2 3Z"/>')
        elif kind in ['C','F','U','M','V']:
            parts.append(f'<circle class="field" cx="{v[0]}" cy="{50-(v[2] if kind in ["C","F"] else v[1])}" r="5"/>')
    for i,(x,y) in enumerate(l['spawn']):parts.append(f'<circle class="unit u{i}" cx="{x}" cy="{48-y}" r="1.8"/>')
    return ''.join(parts)+'</svg>'
def proof(d):
    result=d['testResult']
    if result['status']!='PASS':return '<p>検証記録待ち</p>'
    witness=d.get('basicRouteProof',{});alt=d.get('alternativeRouteProof',{})
    body='<p class="proof">実戦成立：ガン通常弾のみ3条件／推奨機体1条件'+('／固有技の成立検査' if result['featuredTechniqueVerified'] else '')+'</p>'
    body+='<dl><dt>基本の狙い</dt><dd>'+esc(d['basicRoute'])+'</dd><dt>推奨機体の実行例</dt><dd>'+esc(witness.get('description',''))+'</dd><dt>ガンでの代替例</dt><dd>'+esc(alt.get('description',''))+'</dd><dt>敵との関係</dt><dd>'+esc(d['enemyInteraction']['counterplay'])+'</dd><dt>許容と実測</dt><dd>'+esc(d['tolerance'])+' 実測'+str(result['gunActions'][0])+'〜'+str(result['gunActions'][1])+'行動／制限'+str(d['actionBudget'])+'。敵行動を含む探索結果で、人の所要手数ではありません。</dd></dl>'
    return body
sections=[]
for theme in range(20):
    levels=campaign['levels'][theme*5:theme*5+5];cards=[]
    for l in levels:
        d=design[l['id']-1];labels='・'.join(feature_names[f] for f in d['mainGimmicks']) or '環境装置なし';kind='大ボス' if l['boss'] else '中ボス' if l['midboss'] else '通常戦'
        cards.append(f'<article id="stage-{l["id"]}"><header><span>{l["id"]:03}</span><small>{kind} · {esc(d["difficultyBand"])}</small></header>{miniature(l)}<h3>{esc(l["name"])}</h3><p class="goal">{esc(d["learningGoal"])}</p><p class="meta">{esc(labels)}<br>推奨：{esc(names[d["advantage"]["character"]])}</p><details><summary>地形の意図と成立例</summary><p>{esc(d["terrainIntent"])}</p><p>{esc(d["advantage"]["reason"])}</p>{proof(d)}</details></article>')
    sections.append(f'<section class="theme" id="theme-{theme+1}"><div class="theme-title"><span>THEME {theme+1:02} / {theme*5+1:03}—{theme*5+5:03}</span><h2>{esc(levels[0]["themeName"])}</h2><p>{esc(levels[0]["themeGoal"])}</p></div><div class="maps">'+''.join(cards)+'</div></section>')
schedule=''.join(f'<tr><td>{r["stage"] if r["stage"] else "開始時"}</td><td>{esc(r["name"]["ja"])}</td><td>{esc(r["reason"]["ja"])}</td></tr>' for r in crew)
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f2f0e6;color:#173b4b;font:15px/1.75 system-ui,sans-serif}a{color:inherit}main{max-width:1440px;margin:auto;padding:28px 4% 70px}.top{display:flex;justify-content:space-between;gap:20px;font-size:13px}h1{font-size:clamp(32px,5vw,64px);line-height:1.2;letter-spacing:-.04em;margin:35px 0 20px}.lead{font-size:18px;max-width:850px}.eyebrow{font-size:12px;letter-spacing:.2em}.notice{padding:18px 22px;border-left:4px solid #df8b50;background:#e8e3d5;max-width:1000px}.legend{display:flex;gap:18px;flex-wrap:wrap;font-size:13px;margin:22px 0}.swatch{display:inline-block;width:13px;height:13px;border-radius:3px;margin-right:7px;vertical-align:middle}nav{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0}nav a{padding:9px 13px;border:1px solid #577f7d88;border-radius:25px;text-decoration:none;font-size:13px}.theme{padding:38px 0;border-top:1px solid #52777c50;scroll-margin-top:15px}.theme-title>span{font-size:11px;letter-spacing:.15em}.theme-title h2{font-size:29px;line-height:1.3;margin:8px 0}.theme-title p{margin:0 0 22px;color:#496770}.maps{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px}article{border:1px solid #a9bdb5;background:#faf9f1;border-radius:12px;overflow:hidden;min-width:0}article header{display:flex;justify-content:space-between;align-items:center;padding:10px 12px}article header span{font-size:21px;font-weight:800}article header small{font-size:10px}article svg{display:block;width:100%;height:auto}.ground{fill:#51757b;stroke:#bce3c2;stroke-width:.6}.breakable{fill:#a583a6;stroke:#eed5c3;stroke-width:.55}.fixed{fill:#8b9791;stroke:#deead6;stroke-width:.55}.device{stroke:#d2ffe4;stroke-width:1;fill:none}.field{fill:#f3daa022;stroke:#ead89c77;stroke-width:.6}.unit{stroke:#14394d;stroke-width:.5}.u0{fill:#d3ef98}.u1{fill:#ffa883}article h3{font-size:16px;line-height:1.4;margin:13px 12px 7px}.goal{font-size:13px;line-height:1.6;min-height:64px;margin:0 12px}.meta{font-size:11px;margin:10px 12px;color:#4b6e73}details{border-top:1px solid #abbeb350}summary{cursor:pointer;min-height:44px;padding:12px;font-size:12px;font-weight:700}details>p,details>dl{padding:0 12px;font-size:12px}details[open]{background:#eff2e9}.proof{color:#286d59;font-weight:700}dt{font-weight:800;margin:12px 0 4px}dd{margin:0;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse;font-size:13px}td,th{text-align:left;padding:12px;border-bottom:1px solid #5b7a7950;vertical-align:top}td:first-child{white-space:nowrap}footer{margin-top:32px;font-size:12px} @media(max-width:1150px){.maps{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:700px){main{padding:20px 5% 50px}.maps{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.theme-title h2{font-size:25px}.goal{font-size:12px;min-height:80px}article header{padding:8px}article header small{font-size:9px}article h3{font-size:14px;margin:10px 8px}.meta{margin:10px 8px;font-size:10px}summary{font-size:11px;padding:10px 8px}.lead{font-size:16px}td,th{padding:9px 6px}td:last-child{font-size:12px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
nav=''.join(f'<a href="#theme-{n}">{(n-1)*5+1}–{n*5}</a>' for n in range(1,21))
doc='<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ARCLINE 0.13｜100の道と仲間の設計</title><style>'+css+'</style><main><div class="top"><a href="../../">← ARCLINE</a><a href="../../game/dist/?v=0.13.0">ゲームを開く ↗</a></div><p class="eyebrow">DESIGN ATLAS / CAMPAIGN 5.0</p><h1>100の道を、<br>仲間とつなぐ。</h1><p class="lead">地形を一つのカテゴリへ押し込めず、床・山・崖・天井・浮島を組み合わせる。仲間が増えるたび攻略の見方も増える、20テーマの全体図です。</p><aside class="notice">制作者向け・結末までのネタバレがあります。図は実データの有限ポリゴンを使う設計輪郭です。緑が自機、橙が敵、紫が破壊可能、灰が残る支え。自動探索416戦の成立と、人による難易度評価は区別しています。</aside><div class="legend"><span><i class="swatch" style="background:#51757b"></i>床・山・崖</span><span><i class="swatch" style="background:#a583a6"></i>破壊できる壁・天井</span><span><i class="swatch" style="background:#8b9791"></i>残る足場</span><span><i class="swatch" style="background:#bce3c2"></i>反射・装置</span></div><nav aria-label="5面ごとのテーマ">'+nav+'</nav><details><summary>加入順と、難易度の読み方</summary><p>1–10：操作と単一の発見。11–14：コロの転がり。21–24：ソラの高弾道。31–34：リコの1回→2回反射。35–49：準備と組合せ。50–79：射点と手順、61–64でリンの破壊→精密弾。80以降：複数の高さ、先に作る窓、変わる環境。5/15…95は中ボス、10/20…100は大ボスです。</p><table><thead><tr><th>加入面</th><th>仲間</th><th>同行する理由</th></tr></thead><tbody>'+schedule+'</tbody></table></details>'+''.join(sections)+'<footer><p><a href="stage_design.json" download>100面設計JSON</a> ／ <a href="stage_verification.json" download>攻略の実測JSON</a> ／ <a href="STAGES_JA.md" download>意図と解法一覧MD</a> ／ <a href="STORY_JA.md" download>物語全文MD</a> ／ <a href="../../evidence/expedition-013/README.md">検証範囲と未確認</a></p><p>実ゲームの共有データから生成。数値解を暗記する設計ではなく、複数の角度と位置を試せる道を目指します。人の通し評価は今後の確認事項です。</p></footer></main></html>'
(out/'index.html').write_text(doc)
md=['# ARCLINE 0.13 — 全100面の攻略意図と解法','', '制作・レビュー用。結末までのネタバレを含みます。人によるプレイ難易度の測定は未確認です。','', '[地形の全体図](index.html) ／ [詳細データ](stage_design.json) ／ [実戦の操作列](stage_verification.json)','']
for l,d in zip(campaign['levels'],design):
    r=d['testResult'];md += [f'## {l["id"]:03} {l["name"]}', '',f'**{d["difficultyBand"]}｜{d["theme"]}｜推奨：{names[d["advantage"]["character"]]}**','',d['learningGoal'],'',f'地形の意図：{d["terrainIntent"]}',f'基本：{d["basicRoute"]}',f'有利な理由：{d["advantage"]["reason"]}',f'敵との関係：{d["enemyInteraction"]["counterplay"]}',f'行動上限：{d["actionBudget"]}。{d["tolerance"]}','',f'実測代替ルート：{d["alternativeRoute"]}','',f'検証：{r["status"]}。ガン通常弾のみ3乱数条件／推奨機体1条件。' + ('固有技の成立検査も実施。' if r.get('featuredTechniqueVerified') else '')+'全機体全解法、人の難易度は未確認。','']
    if d.get('basicRouteProof'):md.extend(['推奨機体の実行例：'+d['basicRouteProof']['description'],''])
(out/'STAGES_JA.md').write_text('\n'.join(md))
print('Generated visual100-stage atlas and Markdown solution catalogue')
